using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Input;
using Avalonia.Interactivity;
using Avalonia.Threading;
using Avalonia.VisualTree;
using OfficeIMO;
namespace ProjectDesk;
internal static class TimelineValidation {
 public static int Run(string file,string output){Directory.CreateDirectory(output);AppBuilder.Configure<DesktopApp>().UseSkia().UseHeadless(new AvaloniaHeadlessPlatformOptions{UseHeadlessDrawing=false}).SetupWithoutStarting();int checks=0;void Assert(bool ok,string why){if(!ok)throw new Exception(why);checks++;}void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick(3);Dispatcher.UIThread.RunJobs();}
  using var session=new ProjectSession();session.Open(file);string original=session.Document!.ToXml(new(){LossPolicy=OfficeConversionLossPolicy.Allow});var bytes=File.ReadAllBytes(file);string prefs=Path.Combine(output,"views-"+Guid.NewGuid()+".json");var legacy=new ViewPreferences();legacy.TimelineTasks[session.SourcePath!]=[session.Tasks.First().Uid];legacy.Save(prefs);var window=new PlannerWindow(session,prefs);window.Show();Pump();var module=window.Timeline;Assert(module.Lanes.Count==1,"Legacy timeline did not migrate into one lane");Assert(module.SelectedUids.SequenceEqual(new[]{session.Tasks.First().Uid}),"Legacy pinned task lost");string first=module.ActiveId;var task=session.Tasks.First(t=>t.Start.HasValue&&t.Finish.HasValue&&t.Finish>t.Start);module.SetSelection([task.Uid],true);string second=module.AddTimeline("Delivery");Pump();Assert(module.Lanes.Count==2&&module.ActiveId==second,"New active timeline missing");module.SelectLane(first);Pump();var source=module.Canvases[0];var target=module.Canvases[1];var block=source.Blocks.Single(b=>b.Uid==task.Uid);Point from=source.TranslatePoint(block.Bounds.Center,window)!.Value;Point to=target.TranslatePoint(new Point(80,50),window)!.Value;
  window.MouseMove(from);window.MouseDown(from,MouseButton.Left);window.MouseMove(new Point(from.X+10,from.Y),RawInputModifiers.LeftMouseButton);Pump();Assert(module.IsDragging,"Actual pointer gesture did not start drag");window.MouseMove(to,RawInputModifiers.LeftMouseButton);window.MouseUp(to,MouseButton.Left);Pump();Assert(!module.Lanes.Single(l=>l.Id==first).TaskUids.Contains(task.Uid)&&module.Lanes.Single(l=>l.Id==second).TaskUids.Contains(task.Uid),"Pointer drop did not move bar between timelines");Assert(!session.HasEdits&&session.Document.ToXml(new(){LossPolicy=OfficeConversionLossPolicy.Allow})==original,"Timeline drag changed project data");
  module.SelectLane(second);var secondAxis=module.Axis;double ganttZoom=window.Axis.Zoom;secondAxis.SetRange(task.Start!.Value.Date,task.Finish!.Value.Date.AddDays(1));secondAxis.SetZoom(4);Pump();Assert(window.Axis.Zoom==ganttZoom&&!window.Axis.HasCustomRange,"Timeline zoom/range changed Gantt");module.SelectLane(first);Assert(module.Axis.Zoom==1&&!module.Axis.HasCustomRange,"Timeline axes are coupled");window.Axis.SetRange(task.Start.Value.Date.AddDays(-1),task.Finish.Value.Date.AddDays(2));window.Axis.SetZoom(3);module.SelectLane(second);var state=secondAxis.Capture();window.RefreshForValidation();Pump();Assert(secondAxis.Capture()==state&&window.Axis.HasCustomRange&&window.Axis.Zoom==3,"Refresh reset custom dates/zoom");Assert(secondAxis.Finish==task.Finish.Value.Date.AddDays(2),"Finish limit is not inclusive");try{secondAxis.SetRange(task.Finish.Value.Date.AddDays(2),task.Start.Value.Date);Assert(false,"Invalid date range accepted");}catch(ArgumentException){checks++;}Assert(secondAxis.Capture()==state,"Rejected range mutated view");
  secondAxis.Fit();Pump();var secondBlock=target.Blocks.Single(b=>b.Uid==task.Uid);from=target.TranslatePoint(secondBlock.Bounds.Center,window)!.Value;window.MouseMove(from);window.MouseDown(from,MouseButton.Left);window.MouseMove(new Point(from.X+10,from.Y),RawInputModifiers.LeftMouseButton);Pump();Assert(module.IsDragging,"Escape check did not begin actual drag");window.KeyPressQwerty(PhysicalKey.Escape,RawInputModifiers.None);window.KeyReleaseQwerty(PhysicalKey.Escape,RawInputModifiers.None);Pump();window.MouseUp(from,MouseButton.Left);Assert(!module.IsDragging&&module.Lanes.Single(l=>l.Id==second).TaskUids.Contains(task.Uid),"Escape did not cancel drag");
  target.Focus();window.KeyPressQwerty(PhysicalKey.ArrowUp,RawInputModifiers.Alt);window.KeyReleaseQwerty(PhysicalKey.ArrowUp,RawInputModifiers.Alt);Pump();Assert(module.Lanes.Single(l=>l.Id==first).TaskUids.Contains(task.Uid),"Alt+Up did not move selected bar to previous timeline");
  module.SelectLane(second);string third=module.AddTimeline("Milestones");module.RenameTimeline(third,"Release milestones");Pump();Assert(module.Lanes.Single(l=>l.Id==third).Name=="Release milestones","Rename lost timeline identity");var milestone=session.Tasks.FirstOrDefault(t=>t.Start.HasValue&&(t.IsMilestone==true||t.Duration?.Value==0));if(milestone!=null){module.SetSelection([milestone.Uid],true);Pump();var canvas=module.Canvases[2];var hit=canvas.Blocks.Single(b=>b.Uid==milestone.Uid);Assert(hit.Milestone&&canvas.HitBlock(hit.MarkerBounds!.Value.Center)?.Uid==milestone.Uid,"Milestone marker not selectable");module.MoveTask(third,second,milestone.Uid);Assert(module.Lanes.Single(l=>l.Id==second).TaskUids.Contains(milestone.Uid),"Milestone move failed");}
  module.SelectLane(first);module.SetSelection([task.Uid],true);module.Axis.EntireProject();window.Axis.EntireProject();Pump();var chart=window.Gantt;var point=chart.TranslatePoint(new Point(70,60),window)!.Value;var timelineBefore=module.Axis.Capture();var zoomModifier=OperatingSystem.IsMacOS()?RawInputModifiers.Meta:RawInputModifiers.Control;window.MouseWheel(point,new Vector(0,1),zoomModifier);Pump();Assert(window.Axis.Zoom>1&&module.Axis.Capture()==timelineBefore,"Gantt Ctrl/Cmd+wheel did not zoom independently");
  var timelinePoint=module.Canvases[0].TranslatePoint(new Point(80,60),window)!.Value;ganttZoom=window.Axis.Zoom;window.MouseWheel(timelinePoint,new Vector(0,1),zoomModifier);Pump();Assert(module.Axis.Zoom>1&&window.Axis.Zoom==ganttZoom,"Timeline Ctrl/Cmd+wheel did not zoom independently");
  // Exercise the actual View-menu dialogs and their Apply/Cancel paths.
  void Menu(string label){window.GetVisualDescendants().OfType<Menu>().Single().Items.OfType<MenuItem>().Single(m=>Equals(m.Header,"View")).Items.OfType<MenuItem>().Single(m=>Equals(m.Header,label)).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Pump();}
  void Click(Window dialog,string label){dialog.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,label)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
  var beforeDialog=window.Axis.Capture();Menu("Zoom and Gantt Dates…");var dialog=window.OwnedWindows.OfType<DateRangeWindow>().Single();var auto=dialog.GetVisualDescendants().OfType<CheckBox>().Single(c=>c.Name=="AutomaticRange");auto.IsChecked=false;var start=dialog.GetVisualDescendants().OfType<CalendarDatePicker>().Single(c=>c.Name=="StartDate");var finish=dialog.GetVisualDescendants().OfType<CalendarDatePicker>().Single(c=>c.Name=="FinishDate");start.SelectedDate=task.Start.Value.Date;finish.SelectedDate=task.Start.Value.Date.AddDays(-1);Click(dialog,"Apply");Assert(dialog.IsVisible&&window.Axis.Capture()==beforeDialog,"Invalid range dialog changed Gantt or closed");Assert(dialog.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text?.StartsWith("Finish must") ==true),"Invalid date dialog has no error");finish.SelectedDate=task.Finish.Value.Date;dialog.GetVisualDescendants().OfType<NumericUpDown>().Single(c=>c.Name=="DateZoom").Value=250;Click(dialog,"Apply");Assert(!dialog.IsVisible&&window.Axis.Zoom==2.5&&window.Axis.LastDate==task.Finish.Value.Date,"Gantt dialog Apply lost dates/zoom");
  beforeDialog=window.Axis.Capture();Menu("Zoom and Gantt Dates…");dialog=window.OwnedWindows.OfType<DateRangeWindow>().Single();dialog.GetVisualDescendants().OfType<NumericUpDown>().Single(c=>c.Name=="DateZoom").Value=400;Click(dialog,"Cancel");Assert(window.Axis.Capture()==beforeDialog,"Cancel changed Gantt view");
  module.SelectLane(second);var otherLane=module.Lanes.Single(l=>l.Id==first).View;Menu("Timeline Dates…");dialog=window.OwnedWindows.OfType<DateRangeWindow>().Single();dialog.GetVisualDescendants().OfType<CheckBox>().Single(c=>c.Name=="AutomaticRange").IsChecked=false;dialog.GetVisualDescendants().OfType<CalendarDatePicker>().Single(c=>c.Name=="StartDate").SelectedDate=task.Start.Value.Date;dialog.GetVisualDescendants().OfType<CalendarDatePicker>().Single(c=>c.Name=="FinishDate").SelectedDate=task.Finish.Value.Date;dialog.GetVisualDescendants().OfType<NumericUpDown>().Single(c=>c.Name=="DateZoom").Value=300;using(var datesFrame=dialog.CaptureRenderedFrame()!)datesFrame.Save(Path.Combine(output,"zoom-date-dialog.png"));Click(dialog,"Apply");Assert(module.Axis.Zoom==3&&module.Axis.LastDate==task.Finish.Value.Date&&module.Lanes.Single(l=>l.Id==first).View==otherLane&&window.Axis.Capture()==beforeDialog,"Timeline dialog changed another view");
  module.Axis.SetRange(task.Start.Value.Date,task.Finish.Value.Date.AddDays(1));module.Axis.SetZoom(2);window.Axis.SetRange(task.Start.Value.Date.AddDays(-1),task.Finish.Value.Date.AddDays(2));window.Axis.SetZoom(2);Pump();using(var frame=window.CaptureRenderedFrame()!)frame.Save(Path.Combine(output,"multiple-timelines.png"));var saved=ViewPreferences.Load(prefs);Assert(saved.TimelineLayouts.Values.Single().Lanes.Count==3&&saved.GanttAxes.Values.Single().Zoom==2,"Timeline/Gantt preferences not saved");window.CloseForValidation();var restored=new PlannerWindow(session,prefs);restored.Show();Pump();Assert(restored.Timeline.Lanes.Count==3&&restored.Timeline.ActiveId==second,"Timeline structure/active lane not restored");Assert(restored.Timeline.Axis.HasCustomRange&&restored.Timeline.Axis.Zoom==2&&restored.Axis.HasCustomRange&&restored.Axis.Zoom==2,"Independent ranges/zoom not restored");Assert(restored.Timeline.Lanes.Single(l=>l.Id==first).TaskUids.Contains(task.Uid),"Moved bar placement not restored");restored.Timeline.RemoveTimeline(third);restored.Timeline.RemoveTimeline(second);try{restored.Timeline.RemoveTimeline(first);Assert(false,"Last timeline removed");}catch(InvalidOperationException){checks++;}Assert(bytes.SequenceEqual(File.ReadAllBytes(file))&&!session.HasEdits,"Timeline edits modified original file/model");restored.CloseForValidation();Console.WriteLine($"PASS: {checks} multi-timeline checks; pointer drag, escape, keyboard move, milestone hits, independent range/zoom/wheel, migration, persistence, remove and unchanged project.");return 0;
 }
}
